#include "ui/brush/BrushControls.hpp"
#include <QFrame>
#include <QHBoxLayout>
#include <QLabel>
#include <QSlider>
#include <QVBoxLayout>
namespace Skink::Ui::Brush { namespace { QWidget* block(QWidget* parent,const QString& title,const QString& sub,int min,int max,int value,int height,QSlider** out){auto* host=new QWidget(parent);host->setObjectName("controlBlock");auto* row=new QHBoxLayout(host);row->setContentsMargins(0,0,0,0);row->setSpacing(15);auto* frame=new QFrame(host);frame->setObjectName("sliderColumn");frame->setFixedSize(42,height);auto* fl=new QVBoxLayout(frame);fl->setContentsMargins(12,9,12,9);auto* slider=new QSlider(Qt::Vertical,frame);slider->setRange(min,max);slider->setValue(value);fl->addWidget(slider);auto* copy=new QWidget(host);copy->setObjectName("controlCopy");auto* cl=new QVBoxLayout(copy);cl->setContentsMargins(0,8,0,0);cl->setSpacing(4);auto* a=new QLabel(title,copy);a->setObjectName("controlTitle");auto* b=new QLabel(sub,copy);b->setObjectName("controlSubtitle");auto* o=new QLabel(QString::number(value)+(title=="TAMAÑO"?" px":"%"),copy);o->setObjectName("controlOutput");cl->addWidget(a);cl->addWidget(b);cl->addWidget(o);cl->addStretch();connect(slider,&QSlider::valueChanged,o,[o,title](int v){o->setText(QString::number(v)+(title=="TAMAÑO"?" px":"%"));});row->addWidget(frame);row->addWidget(copy);*out=slider;return host;} }
BrushControls::BrushControls(QWidget* parent):QWidget(parent){setObjectName("leftControls");setFixedSize(205,410);auto* l=new QVBoxLayout(this);l->setContentsMargins(0,0,0,0);l->setSpacing(18);QSlider *size,*opacity,*pressure;l->addWidget(block(this,"TAMAÑO","del pincel",1,160,14,128,&size));l->addWidget(block(this,"OPACIDAD","del pincel",5,100,100,128,&opacity));l->addWidget(block(this,"PRESIÓN","Sensibilidad del lápiz",0,100,85,118,&pressure));connect(size,&QSlider::valueChanged,this,&BrushControls::brushSizeChanged);connect(opacity,&QSlider::valueChanged,this,&BrushControls::opacityChanged);connect(pressure,&QSlider::valueChanged,this,&BrushControls::pressureSensitivityChanged);} }
